/**
 * The B3 position a FlowMesh state builds relative to: a block hash at a
 * height on the base chain that the anchoring rules accept as final
 * enough. WHAT is acceptable — the finality depth, and behavior across a
 * base-chain reorg — is an OWNER DECISION (OD-6) enforced by whoever
 * supplies/validates anchors; this struct only names the position.
 */
struct AnchorRef {
    int32_t height{-1};
    uint256 hash;

    SERIALIZE_METHODS(AnchorRef, obj) { READWRITE(obj.height, obj.hash); }

bool ChainAnchorPolicy::Acceptable(const flowmesh::AnchorRef& anchor) const
{
    if (anchor.height < 0 || anchor.hash.IsNull()) return false;
    LOCK(cs_main);
    const CBlockIndex* index{m_chainman.m_blockman.LookupBlockIndex(anchor.hash)};
    if (index == nullptr || index->nHeight != anchor.height) return false;
    const CChain& active{m_chainman.ActiveChain()};
    if (!active.Contains(index)) return false;
    return active.Height() - index->nHeight >= m_min_depth;

